import requests

def test_get_admin_withdrawal_requests_returns_pending_queue():
    base_url = "http://localhost:8000"
    token = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/json"
    }
    url = f"{base_url}/api/admin/withdrawal-requests"

    try:
        response = requests.get(url, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    assert response.status_code == 200, f"Expected status code 200 but got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert isinstance(data, list), f"Expected response to be a list but got {type(data)}"

    # Verify each item in the list has typical withdrawal request fields
    for item in data:
        assert isinstance(item, dict), "Each withdrawal request should be a dictionary"
        assert "id" in item, "Withdrawal request item missing 'id'"
        assert "status" in item, "Withdrawal request item missing 'status'"
        # status should be 'pending' per the test description
        assert item["status"].lower() == "pending", f"Expected withdrawal request status to be 'pending' but got '{item['status']}'"

test_get_admin_withdrawal_requests_returns_pending_queue()